const app=document.querySelector('#app'), modal=document.querySelector('#finish');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=d=>new Date(d).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});
const equipment=(rows,ready=[])=>rows.map(([name,qty,note],i)=>({name,qty,note,ready:ready.includes(i)}));
function seed(){const now=Date.now();return {read:false,events:[
{id:1,beo:'021045',name:'Leadership lunch',type:'Lunch buffet',room:'Wilson Room',floor:'2nd floor',guests:100,start:now+95*60000,team:['Alex','Blair'],changed:true,items:equipment([['Chafers',6,'5 hot dishes + 1 extra station · Revised'],['Dinner plates',100,'1 per guest'],['Serving utensils',6,'1 per buffet station'],['Water pitchers',10,'1 per 10 guests'],['Tray stands',4,'Fixed quantity'],['Bus tubs',3,'Fixed quantity']],[1,3,4])},
{id:2,beo:'021053',name:'Afternoon coffee break',type:'Coffee break',room:'Wilson Room',floor:'2nd floor',guests:80,start:now+195*60000,team:['Alex'],items:equipment([['Coffee urns',2,'1 per 40 guests'],['Coffee cups',80,'1 per guest'],['Saucers',80,'1 per guest'],['Service trays',4,'Fixed quantity']])},
{id:3,beo:'021067',name:'Foundation dinner',type:'Dinner buffet',room:'Grand Ballroom',floor:'4th floor',guests:240,start:now+315*60000,team:['Alex','Jamie','Blair'],items:equipment([['Chafers',8,'8 hot buffet dishes'],['Dinner plates',240,'1 per guest'],['Serving utensils',8,'1 per buffet station'],['Water pitchers',24,'1 per 10 guests'],['Bus tubs',6,'Fixed quantity']])},
{id:4,beo:'021038',name:'Board breakfast',type:'Breakfast buffet',room:'Monroe Room',floor:'2nd floor',guests:40,start:now-30*60000,team:['Alex'],completed:{name:'Alex Lee',at:now-95*60000,photo:null},items:equipment([['Chafers',3,'3 hot buffet dishes'],['Breakfast plates',40,'1 per guest'],['Serving utensils',3,'1 per hot dish']],[0,1,2])}]};}
let state;try{state=JSON.parse(localStorage.getItem('steward-prototype-v1'))||seed();}catch{state=seed();}
let tab='events',filter='all',selected=null,photo=null;
let role=new URLSearchParams(location.search).get('view')||localStorage.getItem('steward-demo-role')||'steward';
function save(){try{localStorage.setItem('steward-prototype-v1',JSON.stringify(state));}catch{toast('Preview saved for this session only.');}}
const ready=e=>e.items.filter(i=>i.ready).length;
const deadline=e=>e.start-60*60000;
function countdown(e){if(e.completed)return 'Setup complete';const secs=Math.floor((deadline(e)-Date.now())/1000),abs=Math.abs(secs),h=Math.floor(abs/3600),m=Math.floor(abs%3600/60),s=abs%60;return `${secs<0?'Overdue by ':''}${h?`${h}h `:''}${String(m).padStart(2,'0')}m ${String(s).padStart(2,'0')}s${secs>=0?' to setup':''}`;}
function toast(s){const el=document.querySelector('#toast');el.textContent=s;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',3500);}
function card(e){const count=ready(e);return `<button class="card" data-event="${e.id}"><div class="card-top"><span class="time">${fmt(e.start)} <span style="color:#8c978c;font-weight:400">· ${esc(e.type)}</span></span><span class="status ${e.completed?'complete':e.changed&&!state.read?'urgent':''}">${e.completed?'✓ Complete':e.changed&&!state.read?'Updated':count?'In progress':'To do'}</span></div><h3>${esc(e.name)}</h3><div class="room"><span>⌖ ${esc(e.room)}</span><span>${e.guests} guests</span></div><div class="progress"><div style="width:${count/e.items.length*100}%"></div></div><div class="card-bottom"><span>${count} of ${e.items.length} items ready</span><span class="${e.completed?'':'countdown'}" data-clock="${e.id}">${countdown(e)}</span></div></button>`;}
function render(){if(role==='supervisor'){supervisorRender();return;}document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));document.querySelector('#badge').hidden=state.read;const today=new Date().toLocaleDateString([],{weekday:'long',month:'long',day:'numeric'});if(selected){detail();return;}if(tab==='events'){const total=state.events.length,done=state.events.filter(e=>e.completed).length;app.innerHTML=`<div class="eyebrow">${today}</div><h1>Let’s get set, Alex.</h1><p class="subtitle">Your events, your checklist. One smooth shift.</p><div class="stats">${[["all",total,"Assigned events"],["todo",total-done,"Still to set"],["done",done,"Complete"]].map(([value,count,label])=>`<button class="stat-button" data-filter="${value}" data-summary aria-pressed="${filter===value}" aria-label="Show ${label.toLowerCase()}: ${count}"><strong>${count}</strong><span>${label}</span></button>`).join("")}</div>${!state.read?'<div class="alert"><span>↻</span><div><strong>A little change to your lunch setup</strong>Leadership lunch now needs 6 chafers. Maria added an extra station.<br><button data-open-change>Review change →</button></div></div>':''}<div class="section-title"><h2>Your lineup</h2><span>In event time order</span></div><div class="filters">${[['all','All events'],['todo','Outstanding'],['done','Complete']].map(([v,t])=>`<button class="filter ${filter===v?'active':''}" data-filter="${v}">${t}</button>`).join('')}</div><div class="cards">${state.events.filter(e=>filter==='all'||(filter==='done'?e.completed:!e.completed)).sort((a,b)=>a.start-b.start).map(card).join('')||'<div class="empty">Nothing here. You’re all caught up.</div>'}</div>`;}else if(tab==='updates'){app.innerHTML=`<div class="eyebrow">Stay in the loop</div><h1>Shift updates.</h1><p class="subtitle">Changes from your supervisor, all in one place.</p><button class="card" data-open-change><div class="card-top"><span class="eyebrow">Equipment revised</span><span class="status urgent">${state.read?'Reviewed':'New'}</span></div><h3>One extra buffet station</h3><p class="note">Maria Santos changed chafers from 5 → 6 for Leadership lunch, BEO 021045. Everything else stays the same.</p><div class="room">⌖ Wilson Room · ${fmt(state.events[0].start)}</div><p class="note">Review event →</p></button>`;}else{app.innerHTML=`<div class="eyebrow">Your profile</div><h1>Alex’s shift.</h1><p class="subtitle">Banquet steward · Today’s operation</p><div class="card shift-list"><div class="row"><span>Supervisor</span><strong>Maria Santos</strong></div><div class="row"><span>Primary location</span><strong>2nd floor</strong></div><div class="row"><span>Working with</span><strong>Blair & Jamie</strong></div><div class="row"><span>Events complete</span><strong>${state.events.filter(e=>e.completed).length} / 4</strong></div></div><p class="note">This is a team prototype with fictional BEOs. Your changes stay in this browser. Reset any time to run another demonstration.</p><button class="reset" id="reset">Reset sample events</button>`;}bind();}
function detail(){if(role==='supervisor'){supervisorDetail();return;}const e=state.events.find(x=>x.id===selected),count=ready(e);app.innerHTML=`<button class="back" id="back">← Back to my events</button><div class="eyebrow">BEO #${e.beo} · ${esc(e.type)}</div><h1>${esc(e.name)}</h1><div class="detail-head"><div class="row" style="margin:0"><span>${esc(e.room)} · ${esc(e.floor)}</span><span>${e.guests} guests</span></div><h2>${fmt(e.start)} event start</h2><div class="room">${e.team.map(p=>`<span class="person"><b>${esc(p[0])}</b>${esc(p)}</span>`).join('')}</div><div class="row"><span>Setup due ${fmt(deadline(e))}</span><strong class="deadline" data-clock="${e.id}">${countdown(e)}</strong></div></div>${e.changed&&!state.read?`<div class="alert"><span>↻</span><div><strong>Equipment changed by Maria</strong>${esc(e.changeDetail||'Chafers increased from 5 to 6 for an extra station.')}<br><button id="ack">Got it, acknowledge change</button></div></div>`:''}<div class="section-title"><h2>Equipment checklist</h2><span>${count} / ${e.items.length} ready</span></div><p class="note">Check an item when its full quantity is ready. You share this setup with ${e.team.length>1?esc(e.team.filter(x=>x!=='Alex').join(' and ')):'your supervisor'}.</p><div>${e.items.map((i,n)=>`<div class="equipment ${i.ready?'ready':''}"><button class="check ${i.ready?'checked':''}" data-item="${n}" aria-label="${i.ready?'Uncheck':'Check'} ${esc(i.name)}" aria-pressed="${i.ready}" ${e.completed?'disabled':''}>${i.ready?'✓':''}</button><div><strong>${esc(i.name)}</strong><p>${esc(i.note)}</p></div><span class="qty">${i.ready?i.qty:0} / ${i.qty}</span></div>`).join('')}</div>${e.completed?`<div class="audit"><strong>✓ Setup complete</strong><br>Completed by ${esc(e.completed.name)} · ${new Date(e.completed.at).toLocaleString()}<br>BEO #${e.beo} · ${e.completed.photo?'Setup photo attached':'Sample completion record'}${e.completed.photo?`<img src="${esc(e.completed.photo)}" alt="Completed event setup">`:''}</div>`:`<button class="primary" id="finish-button" ${count<e.items.length?'disabled':''}>${count===e.items.length?'Complete setup & add photo →':`${e.items.length-count} items left to prepare`}</button><p class="fine">A photo and your completion time will be recorded.</p>`}`;bind();}
function bind(){if(role==='supervisor'){supervisorBind();return;}app.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.event);render();window.scrollTo(0,0);});app.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;const summary=b.hasAttribute('data-summary');render();if(summary){const list=app.querySelector('.cards');list?.scrollIntoView({behavior:'smooth',block:'start'});}});app.querySelectorAll('[data-open-change]').forEach(b=>b.onclick=()=>{selected=1;tab='events';render();window.scrollTo(0,0);});app.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>{const e=state.events.find(x=>x.id===selected),item=e.items[Number(b.dataset.item)];item.ready=!item.ready;save();render();if(ready(e)===e.items.length)openFinish();});const back=document.querySelector('#back');if(back)back.onclick=()=>{selected=null;tab='events';render();};const ack=document.querySelector('#ack');if(ack)ack.onclick=()=>{state.read=true;save();render();toast('Change acknowledged. Your checklist is up to date.');};const finish=document.querySelector('#finish-button');if(finish)finish.onclick=openFinish;const reset=document.querySelector('#reset');if(reset)reset.onclick=()=>{state=seed();save();tab='events';filter='all';render();toast('Sample events reset. Ready for a new demo.');};}
function openFinish(){photo=null;document.querySelector('#photo').value='';document.querySelector('#photo-preview').hidden=true;document.querySelector('#confirm').disabled=true;modal.showModal();}
document.querySelector('#photo').onchange=async event=>{const file=event.target.files[0];if(!file)return;if(!file.type.startsWith('image/'))return toast('Choose an image for your setup photo.');try{const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),scale=Math.min(1,1200/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();photo=canvas.toDataURL('image/jpeg',.75);const preview=document.querySelector('#photo-preview');preview.src=photo;preview.hidden=false;document.querySelector('#confirm').disabled=false;}catch{toast('Could not read this photo. Please choose another.');}};
document.querySelector('#confirm').onclick=()=>{if(!photo)return;const e=state.events.find(x=>x.id===selected);e.completed={name:'Alex Lee',at:Date.now(),photo};addAudit('Setup completed',e,'Alex Lee','All equipment ready. Setup photo attached.',photo);save();modal.close();render();toast('Setup complete. Nice work, Alex!');};
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;selected=null;render();window.scrollTo(0,0);});document.querySelector('.brand').onclick=event=>{event.preventDefault();tab='events';selected=null;render();};document.querySelector('#profile').onclick=()=>{tab=role==='supervisor'?'team':'shift';selected=null;render();};setInterval(()=>document.querySelectorAll('[data-clock]').forEach(el=>{const e=state.events.find(x=>x.id===Number(el.dataset.clock));el.textContent=countdown(e);}),1000);
const demoPeople=[{name:'Alex',full:'Alex Lee',floor:'2nd floor'},{name:'Blair',full:'Blair Chen',floor:'2nd floor'},{name:'Jamie',full:'Jamie Rivera',floor:'4th floor'},{name:'Morgan',full:'Morgan Davis',floor:'4th floor'}];
function addAudit(action,e,actor,detail,photo=null){state.audit??=[];state.audit.unshift({action,beo:e?.beo||'—',event:e?.name||'Operation',actor,detail,at:Date.now(),photo});}
function auditRows(){return [...(state.audit||[]),{action:'Equipment revised',beo:'021045',event:'Leadership lunch',actor:'Maria Santos',detail:'Chafers increased from 5 to 6. Assigned stewards notified.',at:state.events[0].start-105*60000},{action:'Setup completed',beo:'021038',event:'Board breakfast',actor:'Alex Lee',detail:'All equipment ready. Sample completion record.',at:state.events.find(e=>e.id===4)?.completed?.at||Date.now()-95*60000}].sort((a,b)=>b.at-a.at);}
function configureRole(){role=role==='supervisor'?'supervisor':'steward';document.querySelector('#role-switch').textContent=role==='supervisor'?'Steward view ↗':'Supervisor view ↗';document.querySelector('#profile').textContent=role==='supervisor'?'MS':'AL';const buttons=document.querySelectorAll('nav button');const tabs=role==='supervisor'?[['events','▤','Events'],['team','♧','Stewards'],['audit','◷','Audit log']]:[['events','▤','My events'],['updates','♧','Updates'],['shift','◷','My shift']];buttons.forEach((b,i)=>{b.dataset.tab=tabs[i][0];b.innerHTML=`${tabs[i][1]}<span>${tabs[i][2]}${i===1&&role==='steward'?` <i id="badge" ${state.read?'hidden':''}>1</i>`:''}</span>`;});}
document.querySelector('#role-switch').onclick=()=>{role=role==='supervisor'?'steward':'supervisor';localStorage.setItem('steward-demo-role',role);history.replaceState(null,'',`?view=${role}`);selected=null;tab='events';filter='all';configureRole();render();window.scrollTo(0,0);};
function supervisorCard(e){return card(e).replace('</button>',`<div class="mini-label">BEO #${e.beo} · ${esc(e.floor)}</div><div class="team-chips">${e.team.length?e.team.map(n=>`<span>${esc(n)}</span>`).join(''):'<span>Unassigned</span>'}</div></button>`);}
function supervisorRender(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));if(selected){supervisorDetail();return;}const pending=state.events.filter(e=>!e.completed),urgent=pending.filter(e=>deadline(e)-Date.now()<60*60000);if(tab==='events'){app.innerHTML=`<div class="eyebrow">Supervisor · ${new Date().toLocaleDateString([],{weekday:'long',month:'long',day:'numeric'})}</div><h1>A clear view of your shift.</h1><p class="subtitle">Good afternoon, Maria. Here’s how the team is doing.</p><div class="stats"><div><strong>${state.events.length}</strong><span>Today’s events</span></div><div><strong>${pending.length}</strong><span>Outstanding</span></div><div><strong>${urgent.length}</strong><span>Due within 1 hour</span></div></div><div class="super-banner">${urgent.length?'◷ '+urgent.map(e=>esc(e.name)).join(', ')+' needs your attention.':'✓ All upcoming setups are on track.'} Setup deadlines are one hour before event start.</div><div class="super-actions"><button id="import-demo">＋ Import sample BEO</button><button id="rules-demo">Equipment rules</button></div><div class="section-title"><h2>Event overview</h2><span>Ordered by event time</span></div><div class="filters">${[['all','All events'],['todo','Outstanding'],['done','Complete']].map(([v,t])=>`<button class="filter ${filter===v?'active':''}" data-filter="${v}">${t}</button>`).join('')}</div><div class="cards">${state.events.filter(e=>filter==='all'||(filter==='done'?e.completed:!e.completed)).sort((a,b)=>a.start-b.start).map(supervisorCard).join('')||'<p class="empty">No events in this view.</p>'}</div>`;}else if(tab==='team'){app.innerHTML=`<div class="eyebrow">Supervisor · People</div><h1>Your team, in motion.</h1><p class="subtitle">See each steward’s workload, rooms, and remaining setup.</p><div class="summary-grid">${demoPeople.map(p=>{const events=state.events.filter(e=>e.team.includes(p.name)).sort((a,b)=>a.start-b.start),outstanding=events.filter(e=>!e.completed),left=outstanding.reduce((n,e)=>n+e.items.length-ready(e),0);return `<div class="card team-card"><div class="card-top"><span class="avatar">${p.full.split(' ').map(x=>x[0]).join('')}</span><span class="status ${left?'':'complete'}">${left?left+' items outstanding':'Available'}</span></div><h3>${p.full}</h3><p class="note">${p.floor} · ${outstanding.length} upcoming events</p>${events.map(e=>`<button class="event-link" data-event="${e.id}">${fmt(e.start)} · ${esc(e.room)}<br><span class="note">${esc(e.name)} · ${ready(e)}/${e.items.length} ready</span></button>`).join('')||'<p class="note">No events assigned. Ready to help.</p>'}</div>`;}).join('')}</div>`;}else if(tab==='audit'){app.innerHTML=`<div class="eyebrow">Supervisor · Activity</div><h1>Every setup has a story.</h1><p class="subtitle">Who changed what, and when it was completed.</p>${auditRows().map(a=>`<div class="audit-entry"><div class="card-top"><strong>${esc(a.action)}</strong><span class="status ${a.action==='Setup completed'?'complete':''}">${a.action==='Setup completed'?'✓ Complete':'Recorded'}</span></div><p>${esc(a.event)} · BEO #${esc(a.beo)}</p><p class="note">${esc(a.detail)}</p><span>${esc(a.actor)} · ${new Date(a.at).toLocaleString()}</span>${a.photo?`<img src="${esc(a.photo)}" alt="Audited setup photo">`:''}</div>`).join('')}<button class="reset" id="sup-reset">Reset all sample data</button>`;}supervisorBind();}
function supervisorDetail(){const e=state.events.find(e=>e.id===selected);app.innerHTML=`<button class="back" id="sup-back">← Back to event overview</button><div class="eyebrow">BEO #${e.beo} · ${esc(e.type)}</div><h1>${esc(e.name)}</h1><div class="detail-head"><div class="row" style="margin:0"><span>${esc(e.room)} · ${esc(e.floor)}</span><span>${e.guests} guests</span></div><h2>${fmt(e.start)} event start</h2><div class="row"><span>Setup due ${fmt(deadline(e))}</span><strong class="deadline" data-clock="${e.id}">${countdown(e)}</strong></div></div><div class="section-title"><h2>Assigned stewards</h2><span>${e.team.length} assigned</span></div><div class="team-chips">${e.team.map(n=>`<span>${esc(n)}</span>`).join('')||'<span>Unassigned</span>'}</div><button class="outline" id="assign-demo">Manage assignments & suggestions</button><div class="section-title"><h2>Equipment progress</h2><span>${ready(e)} / ${e.items.length} ready</span></div><div class="progress"><div style="width:${ready(e)/e.items.length*100}%"></div></div><div>${e.items.map(i=>`<div class="equipment ${i.ready?'ready':''}"><span class="check ${i.ready?'checked':''}" style="display:grid;place-items:center">${i.ready?'✓':''}</span><div><strong>${esc(i.name)}</strong><p>${esc(i.note)}</p></div><span class="qty">${i.ready?i.qty:0} / ${i.qty}</span></div>`).join('')}</div><button class="outline" id="edit-demo">Adjust equipment quantities</button>${e.completed?`<div class="audit"><strong>✓ Setup complete</strong><br>${esc(e.completed.name)} · ${new Date(e.completed.at).toLocaleString()}${e.completed.photo?`<img src="${esc(e.completed.photo)}" alt="Finished event setup">`:'<br>Sample completion record'}</div>`:'<p class="fine">Outstanding items remain visible until the steward finishes setup.</p>'}`;supervisorBind();}
function supervisorBind(){app.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.event);render();window.scrollTo(0,0);});app.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});const handlers={'sup-back':()=>{selected=null;tab='events';render();},'assign-demo':assignmentDialog,'edit-demo':equipmentDialog,'import-demo':importDialog,'rules-demo':rulesDialog,'sup-reset':()=>{state=seed();save();selected=null;tab='events';render();toast('Sample operation reset.');}};Object.entries(handlers).forEach(([id,fn])=>{const el=document.getElementById(id);if(el)el.onclick=fn;});}
function supervisorModal(title,body,button,onSave){let d=document.querySelector('#super-modal');if(!d){d=document.createElement('dialog');d.id='super-modal';document.body.append(d);}d.innerHTML=`<form method="dialog"><button class="close" aria-label="Close">×</button></form><h2>${title}</h2>${body}<button class="primary" id="super-save">${button}</button>`;d.querySelector('#super-save').onclick=()=>{if(onSave(d)!==false){d.close();save();render();}};d.showModal();}
function assignmentDialog(){const e=state.events.find(x=>x.id===selected),rank=demoPeople.map(p=>{const other=state.events.filter(x=>x.id!==e.id&&!x.completed&&x.team.includes(p.name));const same=other.some(x=>x.room===e.room);return {...p,load:other.length,same,score:(same?100:0)+(p.floor===e.floor?20:0)-other.length*5};}).sort((a,b)=>b.score-a.score);supervisorModal('The right team for the room.',`<p>Suggestions consider nearby rooms and outstanding events. Choose any combination of stewards.</p><div class="suggestion">Suggested: <strong>${rank.slice(0,e.guests>=150?2:1).map(p=>p.full).join(' + ')}</strong></div>${rank.map(p=>`<label class="assign-row"><input type="checkbox" value="${p.name}" ${e.team.includes(p.name)?'checked':''}><span>${p.full}<small>${p.same?'Another setup in this room':p.floor} · ${p.load} other events</small></span></label>`).join('')}`,'Save assignments',d=>{const before=e.team.join(', ');e.team=[...d.querySelectorAll('input:checked')].map(i=>i.value);addAudit('Assignments updated',e,'Maria Santos',`${before||'Unassigned'} → ${e.team.join(', ')||'Unassigned'}`);toast('Assignments saved.');});}
function equipmentDialog(){const e=state.events.find(x=>x.id===selected);supervisorModal('Adjust the setup.',`<p>Changing a quantity updates the steward checklist and adds a change notice. Completed setups reopen when quantities change.</p>${e.items.map((i,n)=>`<label class="assign-row"><span>${esc(i.name)}</span><input class="qty-edit" type="number" min="1" max="10000" value="${i.qty}" data-qty="${n}" aria-label="${esc(i.name)} quantity"></label>`).join('')}<label class="form-field">Reason for change<input id="change-reason" placeholder="Example: Added a buffet station" maxlength="200"></label>`,'Save & notify stewards',d=>{const inputs=[...d.querySelectorAll('[data-qty]')];if(inputs.some(i=>!Number.isInteger(Number(i.value))||Number(i.value)<1||Number(i.value)>10000)){toast('Enter whole quantities from 1 to 10,000.');return false;}const changes=[];inputs.forEach(i=>{const item=e.items[Number(i.dataset.qty)],qty=Number(i.value);if(qty!==item.qty){changes.push(`${item.name}: ${item.qty} → ${qty}`);item.qty=qty;item.ready=false;item.note='Supervisor adjustment · Revised';}});if(changes.length){e.completed=null;e.changed=true;state.read=false;e.changeDetail=changes.join('; ');addAudit('Equipment revised',e,'Maria Santos',changes.join('; ')+'. '+d.querySelector('#change-reason').value.trim());toast('Checklist updated. Change notice added.');}else toast('No quantities changed.');});}
function importDialog(){supervisorModal('Import a sample BEO.',`<p>This preview simulates an import. It adds a fictional event; PDF extraction is part of the full app.</p><div class="suggestion"><strong>BEO #021081 · Executive reception</strong><br>Grand Ballroom · 160 guests · Dinner buffet<br>Six hot dishes · Six chafers · Multiple stewards</div><label class="form-field">Event name<input id="sample-name" value="Executive reception" maxlength="100"></label>`,'Add sample event',d=>{if(state.events.some(e=>e.beo==='021081')){toast('This sample BEO has already been imported.');return false;}const name=d.querySelector('#sample-name').value.trim();if(!name){toast('Enter an event name.');return false;}const e={id:5,beo:'021081',name,type:'Dinner buffet',room:'Grand Ballroom',floor:'4th floor',guests:160,start:Date.now()+255*60000,team:[],items:equipment([['Chafers',6,'6 hot buffet dishes'],['Dinner plates',160,'1 per guest'],['Serving utensils',6,'1 per buffet station'],['Bus tubs',4,'Fixed quantity']])};state.events.push(e);addAudit('BEO imported',e,'Maria Santos','Sample BEO reviewed. Event awaiting assignment.');toast('Sample imported. Assign your stewards next.');});}
function rulesDialog(){state.rules??=[{name:'Chafers',basis:'Per hot buffet dish',qty:1},{name:'Dinner plates',basis:'Per guest',qty:1},{name:'Serving utensils',basis:'Per hot buffet dish',qty:1},{name:'Bus tubs',basis:'Fixed per event',qty:3}];supervisorModal('Buffet equipment rules.',`<p>Manage the sample mapping for buffet events. Changes are saved for this preview; existing event checklists stay as reviewed.</p>${state.rules.map((r,n)=>`<label class="rule-row"><span><strong>${r.name}</strong><small>${r.basis}</small></span><input class="qty-edit" type="number" min="1" max="100" value="${r.qty}" data-rule="${n}" aria-label="${r.name} rule quantity"></label>`).join('')}<p class="note">Example: 5 hot dishes × 1 chafer = 5 chafers. Guest count controls the plate calculation.</p>`,'Save sample rules',d=>{const inputs=[...d.querySelectorAll('[data-rule]')];if(inputs.some(i=>!Number.isInteger(+i.value)||+i.value<1||+i.value>100)){toast('Enter whole quantities from 1 to 100.');return false;}inputs.forEach(i=>state.rules[+i.dataset.rule].qty=+i.value);addAudit('Equipment rules updated',null,'Maria Santos','Sample buffet mapping saved.');toast('Sample rules saved.');});}
configureRole();render();
